package br.com.flexclock.common;

import java.security.SecureRandom;
import java.time.Instant;
import java.util.Base64;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

/**
 * Identity of the live backend process: process id, listen address and port, start instant and the
 * per run instance identifier generated by a cryptographically secure random generator.
 *
 * <p>The identifier is a compensating control for the loopback surface: the desktop client and the
 * MCP sidecar present it on every request and the backend rejects a request without it or with an
 * identifier that does not belong to the live process. This is process continuity on the same
 * machine, not user authentication (decision 0050).
 *
 * <p>The descriptor also publishes the contract version the process speaks and the database schema
 * version it migrated to, so a client can reject a divergent major version before it sends any call
 * and can report which schema it is talking to (requirements RF-007 and RF-102).
 *
 * <p>The address and port are bound by {@link br.com.flexclock.security.InstanceDescriptorWriter} as
 * soon as the web server publishes the effective listen port.
 */
@Component
public class InstanceDescriptor {

	/** Request header that carries the per run instance identifier. */
	public static final String INSTANCE_ID_HEADER = "X-FlexClock-Instance-Id";

	private static final int INSTANCE_ID_BYTES = 32;

	private final String instanceId;
	private final long pid;
	private final Instant startedAt;
	private final String contractVersion;

	private volatile String address;
	private volatile int port;

	/**
	 * Creates the descriptor of the current process and generates its instance identifier.
	 *
	 * @param address the configured listen address
	 * @param port the configured listen port, zero when the port is assigned at startup
	 */
	public InstanceDescriptor(@Value("${server.address:127.0.0.1}") String address,
			@Value("${server.port:0}") int port) {
		this.instanceId = newInstanceId();
		this.pid = ProcessHandle.current().pid();
		this.startedAt = Instant.now();
		this.contractVersion = ContractVersion.VERSION;
		this.address = address;
		this.port = port;
	}

	private static String newInstanceId() {
		byte[] bytes = new byte[INSTANCE_ID_BYTES];
		new SecureRandom().nextBytes(bytes);
		return Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);
	}

	/**
	 * Binds the effective listen address and port once the web server is ready.
	 *
	 * @param address the effective listen address
	 * @param port the effective listen port
	 */
	public void bind(String address, int port) {
		this.address = address;
		this.port = port;
	}

	/**
	 * Returns the per run instance identifier.
	 *
	 * @return the instance identifier
	 */
	public String instanceId() {
		return instanceId;
	}

	/**
	 * Returns the process id of the live backend.
	 *
	 * @return the process id
	 */
	public long pid() {
		return pid;
	}

	/**
	 * Returns the instant when this process started.
	 *
	 * @return the start instant
	 */
	public Instant startedAt() {
		return startedAt;
	}

	/**
	 * Returns the contract version the live process speaks.
	 *
	 * <p>It is published in the descriptor so a client can reject a divergent major version before it
	 * sends any request (requirement RF-102).
	 *
	 * @return the contract version
	 */
	public String contractVersion() {
		return contractVersion;
	}

	/**
	 * Returns the effective listen address.
	 *
	 * @return the listen address
	 */
	public String address() {
		return address;
	}

	/**
	 * Returns the effective listen port, zero while the port is still unknown.
	 *
	 * @return the listen port
	 */
	public int port() {
		return port;
	}
}
